export function createMemo(fetchValue) {
  const cache = new Map();

  return {
    get(key) {
      if (cache.has(key)) return cache.get(key);

      let pending;
      pending = Promise.resolve()
        .then(() => fetchValue(key))
        .catch(reason => {
          cache.delete(key);
          throw reason;
        });

      cache.set(key, pending);
      return pending;
    },

    has(key) {
      return cache.has(key);
    }
  };
}
